using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class RemainingSafetyFix {public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");const string E="Assets/Afrer_Seconds/05.Model/Environment/B5/",P="Assets/Afrer_Seconds/05.Model/Props/B5/";string path=E+"RD_VB_SafetyEquipment.fbx";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.isReadable=true;mi.importAnimation=false;foreach(string n in new[]{"Coat","Steel","Dark","Hazard","Accent"}){var m=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/RD_"+(n=="Accent"?"Teal":n)+".mat");mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"RD_"+n),m);}mi.SaveAndReimport();var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var vb=root.Find("Remaining_Domes_Art/VB");vb.Find("TA_VA_SafetyEquipment").gameObject.SetActive(false);if(!vb.Find("RD_VB_SafetyEquipment")){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),vb);g.name="RD_VB_SafetyEquipment";g.transform.localPosition=Vector3.zero;g.transform.localRotation=Quaternion.identity;foreach(var mf in g.GetComponentsInChildren<MeshFilter>())mf.gameObject.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;}Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{fireCabinet="north wall",intercom="west wall",T18clear=true};}}
